head.script:
var n = 0;
scwin.btn_trigger1_onclick = function() {
    tabControl1.addTab("cmcm011" + n++, {
        "label": "공통코드등록",
        "title": "공통코드등록",
        "openAction": "new",
        "closable": "true"
    }, {
        "src": "tabControl_tabPosition_WEFF-718_(WSQ-4044)_tab.xml",
        "wframe": true,
        "scope": true,
        "alwaysDraw": "true"
    });
};
scwin.btn_trigger2_onclick = function() {
    tabControl2.addTab("cmcm011" + n++, {
        "label": "공통코드등록",
        "title": "공통코드등록",
        "openAction": "new",
        "closable": "true"
    }, {
        "src": "tabControl_tabPosition_WEFF-718_(WSQ-4044)_tab.xml",
        "wframe": true,
        "scope": true,
        "alwaysDraw": "true"
    });
};
scwin.onpageload = function() {
    scwin.btn_trigger1_onclick();
    scwin.btn_trigger2_onclick();
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "parseInt(WebSquare.wUnit.getJq('#tabControl2_contents_content1_body').width()) == 428", "true");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.n = 0;
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
